/* CALC-FARMACOS-NEUROLOGIA-MODULE-I18N-T-OWNER-FIX-V1-B-R0 START */
/* Module-owned bilingual helper.
   neurologia.js uses a three-argument locale-selection contract, while
   the application global translator is a translation-key resolver.
   independent from that global symbol. */
function _mcNeurologiaT(lang, pt, es) {
  const normalized = String(lang == null ? 'pt' : lang).trim().toLowerCase();
  return normalized.startsWith('es') ? es : pt;
}
/* CALC-FARMACOS-NEUROLOGIA-MODULE-I18N-T-OWNER-FIX-V1-B-R0 END */

